enum cmd_op { CMD_RESERVE_STOCK, CMD_CANCEL_ORDER };
struct command {
    enum cmd_op op;                       /* the discriminator that is validated on receipt */
    union {
        struct { int order_id; int qty; } reserve;
        struct { int order_id; } cancel;
    } args;
};
static void (*const handlers[])(const struct command *) = { on_reserve, on_cancel };
void dispatch(const struct command *c) { handlers[c->op](c); }
